vector<bool> is_prime;

void sieve() {
    is_prime.assign(MAX_PRIME + 1, true);
    is_prime[0] = is_prime[1] = false;
    for (int i = 2; i <= MAX_PRIME; i++) {
        if (is_prime[i]) {
            primes.push_back(i);
            for (long long j = (long long)i * i; j <= MAX_PRIME; j += i) {
                is_prime[j] = false;
            }
        }
    }
}

// Check if n is prime
bool isPrime(ll n) {
    if (n < 2) return false;
    if (n <= MAX_PRIME) return is_prime[n];
    for (int p : primes) {
        if ((ll)p * p > n) break;
        if (n % p == 0) return false;
    }
    return true;
}

// Generate all divisors of n
vector<ll> getDivisors(ll n) {
    vector<ll> divisors;
    for (ll i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            divisors.push_back(i);
            if (i != n / i) {
                divisors.push_back(n / i);
            }
        }
    }
    return divisors;
}

// Sum of divisors function sigma(n)
ll sigma(ll n) {
    if (n == 1) return 1;
    ll result = 1;
    ll temp = n;
    for (int p : primes) {
        if ((ll)p * p > temp) break;
        if (temp % p == 0) {
            ll term = 1;
            ll power = 1;
            while (temp % p == 0) {
                temp /= p;
                power *= p;
                term += power;
            }
            result *= term;
        }
    }
    if (temp > 1) {
        // temp is a prime factor
        result *= (1 + temp);
    }
    return result;
}

