#include <vector>
#include <cmath>
#include <algorithm>

using namespace std;

typedef long long ll;

// Check if n is prime
bool isPrime(ll n) {
    if (n < 2) return false;
    if (n == 2) return true;
    if (n % 2 == 0) return false;
    for (ll i = 3; i * i <= n; i += 2) {
        if (n % i == 0) return false;
    }
    return true;
}

// Get prime factorization of n
// Returns vector of (prime, exponent) pairs
vector<pair<ll, int>> factorize(ll n) {
    vector<pair<ll, int>> factors;
    for (ll i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            int exp = 0;
            while (n % i == 0) {
                exp++;
                n /= i;
            }
            factors.push_back({i, exp});
        }
    }
    if (n > 1) {
        factors.push_back({n, 1});
    }
    return factors;
}

// Generate all divisors of n from its prime factorization
vector<ll> getDivisors(vector<pair<ll, int>>& factors) {
    vector<ll> divisors = {1};
    for (auto& p : factors) {
        ll prime = p.first;
        int exp = p.second;
        int currentSize = divisors.size();
        ll power = 1;
        for (int e = 1; e <= exp; e++) {
            power *= prime;
            for (int i = 0; i < currentSize; i++) {
                divisors.push_back(divisors[i] * power);
            }
        }
    }
    return divisors;
}

