using namespace std;

typedef long long ll;

// Check if n is prime
bool isPrime(ll n) {
    if (n < 2) return false;
    if (n == 2) return true;
    if (n % 2 == 0) return false;
    for (ll i = 3; i * i <= n; i += 2) {
        if (n % i == 0) return false;
    }
    return true;
}

// Get prime factorization of n
vector<pair<ll, int>> primeFactorization(ll n) {
    vector<pair<ll, int>> factors;
    for (ll i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            int count = 0;
            while (n % i == 0) {
                count++;
                n /= i;
            }
            factors.push_back({i, count});
        }
    }
    if (n > 1) {
        factors.push_back({n, 1});
    }
    return factors;
}

// Calculate sigma(n) - sum of divisors of n
// sigma(n) = product of (p^(k+1) - 1) / (p - 1) for each prime factor p^k
ll sigma(ll n) {
    if (n <= 0) return 0;
    vector<pair<ll, int>> factors = primeFactorization(n);
    ll result = 1;
    for (auto &factor : factors) {
        ll p = factor.first;
        int k = factor.second;
        // Calculate (p^(k+1) - 1) / (p - 1)
        ll term = 1;
        ll p_power = 1;
        for (int i = 0; i <= k; i++) {
            term += p_power;
            p_power *= p;
        }
        result *= term;
    }
    return result;
}

